#novel_plot_control_bar .npc_pin_adv>summary:hover{color:inherit!important;}
#novel_plot_control_bar .npc_pin_body{display:flex!important;flex-direction:column!important;gap:10px!important;padding:2px 0 4px!important;}
#novel_plot_control_bar .npc_pin_mode{display:flex!important;flex-direction:row!important;gap:16px!important;font-size:12.5px!important;}
