<div id="novel_importer_container" class="extension_settings">
<div class="flex-container flexFlowColumn">
\x3c!-- Mode Switch --\x3e
<div class="novel_mode_switch" style="display:flex;gap:6px;margin-bottom:8px;padding:5px;border-radius:6px;background:rgba(255,255,255,0.04);">
<label class="menu_button" style="flex:1;text-align:center;cursor:pointer;">
<input type="radio" name="novel_mode" value="import" checked style="display:none;" />
普通导入
</label>
<label class="menu_button" style="flex:1;text-align:center;cursor:pointer;">
<input type="radio" name="novel_mode" value="worldbook" style="display:none;" />
世界书注入
</label>
</div>
\x3c!-- Import mode controls --\x3e
<div class="novel_import_mode_section">
<input type="file" id="novel_txt_file" accept=".txt" style="display:none;" />
<label for="novel_txt_file" class="menu_button">选择 TXT 小说</label>
<label>TXT 编码</label>
<select id="novel_file_encoding" class="text_pole">
<option value="auto" selected>自动检测</option>
<option value="utf-8">UTF-8</option>
<option value="gb18030">GBK / GB18030</option>
</select>
<div class="novel_button_row">
<button id="novel_clear_btn" class="menu_button">清空小说</button>
</div>
<div id="novel_stats_row" class="novel_stats_row">
<div id="novel_stats" class="wide100p">
字符数: 0<br>
章节: 0<br>
预计导入楼层: 0
</div>
<div class="novel_import_action">
<button id="novel_import_btn" class="menu_button">导入小说内容</button>
<div id="novel_import_progress" class="novel_import_progress"></div>
</div>
</div>
<details class="novel_panel novel_section_group novel_import_mode_section" open>
<summary><b>导入设置</b></summary>
<div class="novel_section_body">
<div class="novel_section_title">角色模式</div>
<select id="novel_role_mode" class="text_pole">
<option value="assistant">AI消息</option>
<option value="user">用户消息</option>
<option value="alternate_ai">AI / 用户交替（AI先发）</option>
<option value="alternate_user">AI / 用户交替（用户先发）</option>
</select>
<label class="checkbox_label">
<input type="checkbox" id="novel_one_chapter_per_message" />
一章一楼
</label>
<div id="novel_by_length_options" class="novel_import_mode_section">
<label>每楼字数</label>
<input class="text_pole" type="number" id="novel_chunk_size" value="1200" min="100" step="100" />
</div>
<div id="novel_import_range_options" class="novel_import_mode_section">
<div class="novel_section_title">导入范围</div>
<select id="novel_import_range_mode" class="text_pole">
<option value="all">全部导入</option>
<option value="chapter">按章节范围</option>
<option value="floor">按楼层范围</option>
</select>
</div>
<div id="novel_chapter_range_wrap" class="novel_range_wrap novel_import_mode_section">
<label>章节范围</label>
<div class="novel_range_row">
<input class="text_pole" type="number" id="novel_import_chapter_start" min="0" value="1" placeholder="起始章" />
<input class="text_pole" type="number" id="novel_import_chapter_end" min="0" value="1" placeholder="结束章" />
</div>
</div>
<div id="novel_floor_range_wrap" class="novel_range_wrap novel_import_mode_section">
<label>楼层范围</label>
<div class="novel_range_row">
<input class="text_pole" type="number" id="novel_import_floor_start" min="1" value="1" placeholder="起始楼" />
<input class="text_pole" type="number" id="novel_import_floor_end" min="1" value="1" placeholder="结束楼" />
</div>
</div>
</div>
</details>
</div>
\x3c!-- World Book section --\x3e
<div class="novel_worldbook_section" style="display:none;">
<details class="novel_panel" open>
<summary><b>章节选择</b></summary>
<div id="novel_wb_chapter_list" class="novel_section_body">
<div class="novel_empty_hint">请先选择 TXT 文件</div>
</div>
</details>
<details class="novel_panel" open>
<summary><b>注入配置</b></summary>
<div class="novel_section_body">
<div class="novel_section_title">插入位置</div>
<select id="novel_wb_position" class="text_pole">
<option value="before_char_def">角色定义前 (↑ Char)</option>
<option value="after_char_def">角色定义后 (↓ Char)</option>
<option value="before_example_mes">示例消息前 (↑ EM)</option>
<option value="after_example_mes">示例消息后 (↓ EM)</option>
<option value="before_authors_note">作者注释前 (↑ AN)</option>
<option value="after_authors_note">作者注释后 (↓ AN)</option>
<option value="system_depth">[系统] 插入深度 @D</option>
<option value="user_depth">[用户 1] 插入深度 @D</option>
<option value="assistant_depth">[AI 1] 插入深度 @D</option>
</select>
<div class="novel_align_start" style="display:flex;gap:8px;margin-top:8px;">
<div style="flex:1;display:none;" id="novel_wb_depth_label">
<div class="novel_section_title">深度 @D</div>
<input id="novel_wb_depth" class="text_pole" type="number" min="1" value="5" style="display:none;" />
</div>
<div style="flex:1;">
<div class="novel_section_title">顺序 / Order</div>
<input id="novel_wb_order" class="text_pole" type="number" min="0" value="100" />
<div class="novel_empty_hint" style="padding:2px 0;font-size:0.82em;">用于支持顺序字段的酒馆提示管理器；手动注入时会写入消息 metadata。</div>
</div>
</div>
<div style="display:flex;gap:8px;margin-top:8px;">
<div style="flex:1;">
<div class="novel_section_title">前置文字</div>
<input id="novel_wb_content_prefix" class="text_pole" type="text" placeholder="&lt;小说原文&gt;" />
</div>
<div style="flex:1;">
<div class="novel_section_title">后置文字</div>
<input id="novel_wb_content_suffix" class="text_pole" type="text" placeholder="&lt;/小说原文&gt;" />
</div>
</div>
<div class="novel_wb_persist_toggle" style="display:flex;gap:8px;margin-top:8px;padding:6px 8px;border-radius:6px;background:rgba(255,255,255,0.04);align-items:center;">
<span style="opacity:0.8;font-size:0.9em;">注入方式:</span>
<label class="menu_button" style="flex:1;text-align:center;cursor:pointer;font-size:0.9em;">
<input type="radio" name="novel_wb_persist" value="once" checked style="display:none;" />
只持续一次
</label>
<label class="menu_button" style="flex:1;text-align:center;cursor:pointer;font-size:0.9em;">
<input type="radio" name="novel_wb_persist" value="always" style="display:none;" />
一直持续
</label>
</div>
<div id="novel_wb_persist_status" style="font-size:0.85em;opacity:0.7;margin-top:4px;padding:0 8px;">注入方式: 只持续一次</div>
<div id="novel_wb_entry_status" class="novel_replace_stats" style="margin-top:8px;">尚未准备注入条目</div>
<div class="novel_button_row" style="margin-top:8px;">
<button id="novel_wb_prepare" class="menu_button">准备注入</button>
<button id="novel_wb_update" class="menu_button" style="display:none;">更新注入内容</button>
<button id="novel_wb_clear" class="menu_button danger_button">清空并关闭</button>
<button id="novel_wb_delete" class="menu_button danger_button">删除条目</button>
<button id="novel_wb_save" class="menu_button">保存配置</button>
</div>
</div>
</details>
</div>
\x3c!-- Search & Replace --\x3e
<details class="novel_panel novel_section_group">
<summary><b>搜索替换</b></summary>
<div class="novel_section_body">
<div class="novel_search_row">
<input id="novel_search_keyword" class="text_pole" type="text" placeholder="输入关键词搜索" />
<button id="novel_search_btn" class="menu_button">搜索</button>
<button id="novel_replace_btn" class="menu_button">替换</button>
<button id="novel_batch_replace_btn" class="menu_button">批量替换</button>
</div>
<label class="checkbox_label">
<input type="checkbox" id="novel_search_case_sensitive" />
搜索时区分大小写
</label>
<label class="checkbox_label">
<input type="checkbox" id="novel_only_hit_items" />
只显示命中章节/楼层
</label>
<div id="novel_search_results" class="wide100p">
<div class="novel_empty_hint">输入关键词后搜索</div>
</div>
</div>
</details>
<details id="novel_chapter_panel" class="novel_panel" open>
<summary><b>章节预览</b></summary>
<div id="novel_chapter_preview" class="wide100p">
<div class="novel_empty_hint">暂无章节</div>
</div>
</details>
<details id="novel_floor_panel" class="novel_panel novel_import_mode_section">
<summary><b>楼层预览</b></summary>
<div id="novel_floor_preview" class="wide100p">
<div class="novel_empty_hint">暂无楼层</div>
</div>
</details>
</div>
</div>
