(() => {
  'use strict';

  // 防止脚本被重复执行导致监听器叠加（真机已知坑：ST 可能重复执行脚本）
  if (window.__DOUPO_WB_AGENT__) {
    try { window.__DOUPO_WB_AGENT__.destroy(); } catch (_) {}
  }

  // ================= 可调配置 =================
  const CONFIG = {
    STAGE_VAR: '阶段',              // 当前剧情阶段：chat 变量名（状态组件定稿后在此改名）
    DEFAULT_STAGE: 1,               // 变量缺失/非法时的兜底阶段
    STAGE_MAX: 9,

    KEYWORD_SCAN_FLOORS: 3,         // 关键词层扫描最近几楼正文
    RETRIEVAL_CONTEXT_FLOORS: 4,    // 分类检索看到的最近几楼剧情
    RETRIEVAL_FLOOR_CHARS: 600,     // 检索上下文每楼截断字符数

    KEYWORD_TOKEN_BUDGET: 8000,     // 关键词层注入 token 上限（不设条目数上限）
    RETRIEVAL_TOKEN_BUDGET: 6000,   // 检索层注入 token 上限（不设条目数上限）
    CHARS_PER_TOKEN: 1.8,           // 中文粗算：tokens ≈ 字符数 / 1.8

    INJECT_DEPTH: 4,                // 注入深度：0 = 紧贴最新楼层，越大越靠提示词前部
    INJECT_ROLE: 'system',
    PERSIST_MISS_FLOORS: 2,         // 持续在场：连续未命中达到该楼数才撤下

    LOG_KEEP: 30,                   // wb_log 在 chat 变量里保留的最近记录条数
    // 检索类目。rule 类条目是常驻条目（导出时 constant、全阶段常开），
    // 永远在提示词里，不需要也不应该走检索，所以不在列表中。
    CATEGORIES: [
      { id: 'char', name: '人物' },
      { id: 'place', name: '地点' },
      { id: 'faction', name: '势力' },
      { id: 'event', name: '事件' },
      { id: 'rel', name: '关系' },
    ],
  };
  const INJECT_ID = 'doupo-wb-agent-inject'; // 注入标识：uninject 用它撤旧注入，必须唯一且固定

  // ================= API 防御获取 =================
  // 酒馆助手把 API 同时注入为自由全局函数和 window.TavernHelper 属性，
  // 两种访问形式等效（C1 §3），这里两边都查，缺了就记降级，不让脚本崩。
  const TH = (typeof window.TavernHelper === 'object' && window.TavernHelper) || null;
  const fn = (name) => {
    if (typeof window[name] === 'function') return window[name].bind(window);
    if (TH && typeof TH[name] === 'function') return TH[name].bind(TH);
    return null;
  };
  const api = {
    getWorldbook: fn('getWorldbook'),
    getCharWorldbookNames: fn('getCharWorldbookNames'),
    getChatMessages: fn('getChatMessages'),
    getVariables: fn('getVariables'),
    replaceVariables: fn('replaceVariables'),
    generateRaw: fn('generateRaw'),
    injectPrompts: fn('injectPrompts'),
    uninjectPrompts: fn('uninjectPrompts'),
    eventOn: fn('eventOn'),
    eventMakeFirst: fn('eventMakeFirst'),
  };
  const EV = window.tavern_events || {};

  // ================= 宿主窗口访问（C1 §10：UI 必须挂到 ST 主窗口） =================
  function hostWindow() {
    try {
      if (window.parent && window.parent !== window && window.parent.document) return window.parent;
    } catch (_) {}
    return window;
  }
  function hostDocument() {
    try { return hostWindow().document || document; } catch (_) { return document; }
  }

  // ================= 运行状态（脚本内存，重载后重建） =================
  const state = {
    worldbookName: null,
    index: [],            // 解析后的条目索引：{entryId, name, category, stage, uid, content, summary, keys}
    snapshot: [],         // 分类检索层最新完成的候选：[{id, cat, reason}]
    lastInjected: [],     // 上一楼实际注入的条目（_tier 标记来源层：kw/ret/keep）
    missCount: {},        // entryId -> 连续未命中楼数
    busy: false,          // 检索进行中标记（防并发）
    pending: false,       // 检索期间又来触发请求 → 补跑一轮
    initError: null,      // 初始化失败信息（悬浮窗状态点显示）
  };
  const disposers = [];   // 所有监听器的取消函数，destroy 时统一调用

  // ================= 日志（wb_log 写入 chat 变量，供验收查账） =================
  function log(kind, detail) {
    const record = { t: new Date().toISOString().slice(11, 19), kind, detail };
    try {
      if (!api.getVariables || !api.replaceVariables) return;
      const vars = api.getVariables({ type: 'chat' }) || {};
      const arr = Array.isArray(vars.wb_log) ? vars.wb_log : [];
      arr.push(record);
      while (arr.length > CONFIG.LOG_KEEP) arr.shift();
      vars.wb_log = arr;
      api.replaceVariables(vars, { type: 'chat' }); // wb_log 键由本脚本独占，全量替换安全
    } catch (_) { /* 日志失败不影响主流程 */ }
  }

  function readLog() {
    try {
      const vars = api.getVariables ? api.getVariables({ type: 'chat' }) : null;
      return Array.isArray(vars && vars.wb_log) ? vars.wb_log : [];
    } catch (_) { return []; }
  }

  // ================= 阶段读取（agent 与状态组件的唯一接口） =================
  function currentStage() {
    try {
      const vars = api.getVariables ? api.getVariables({ type: 'chat' }) : null;
      const n = Number(vars && vars[CONFIG.STAGE_VAR]);
      if (Number.isInteger(n) && n >= 1 && n <= CONFIG.STAGE_MAX) return n;
    } catch (_) {}
    return CONFIG.DEFAULT_STAGE;
  }

  // ================= 索引构建 =================
  // comment 固定格式：ID｜中文名｜类别｜P<n>（schema.md 契约），是整个索引的唯一来源。
  function parseComment(comment) {
    const parts = String(comment || '').split('｜').map((s) => s.trim());
    if (parts.length < 4) return null;
    const m = parts[3].match(/^P(\d+)$/i);
    if (!m) return null;
    return { entryId: parts[0], name: parts[1], category: parts[2].toLowerCase(), stage: Number(m[1]) };
  }

  // 目录行需要的一句话简介：优先取正文「一句话：」行，兜底取第一个非标题行
  function extractSummary(content) {
    const text = String(content || '');
    const m = text.match(/一句话：(.+)/);
    if (m) return m[1].trim().slice(0, 60);
    const line = text.split('\n').map((s) => s.trim()).find((s) => s && !s.startsWith('#'));
    return line ? line.slice(0, 60) : '';
  }

  // 关键词集合：条目自带 keys（导出时 = name + aliases + tags）+ 中文名兜底。
  function collectKeys(entry, parsed) {
    const keys = new Set();
    const strategy = entry.strategy || {};
    (Array.isArray(strategy.keys) ? strategy.keys : []).forEach((k) => k && keys.add(String(k)));
    (Array.isArray(entry.key) ? entry.key : []).forEach((k) => k && keys.add(String(k))); // 兼容旧字段名
    keys.add(parsed.name);
    return [...keys].filter((k) => k.length >= 2);
  }

  async function rebuildIndex() {
    try {
      if (!api.getCharWorldbookNames || !api.getWorldbook) {
        state.initError = '酒馆助手世界书 API 不可用';
        log('init', state.initError + '，agent 停用（仅剩酒馆原生关键词触发）');
        return;
      }
      const names = await api.getCharWorldbookNames('current'); // 参数 'current' 必填
      const wbName = names && names.primary;
      if (!wbName) {
        state.initError = '角色卡未绑定主世界书';
        log('init', state.initError + '，agent 空转（先在旗子面板导入并在角色卡绑定）');
        return;
      }
      state.worldbookName = wbName;
      const entries = await api.getWorldbook(wbName); // 返回数组，不是键值对象
      state.index = (entries || [])
        .filter((e) => e && e.enabled !== false && (e.comment || e.name))
        .map((e) => {
          const parsed = parseComment(e.comment || e.name);
          if (!parsed) return null;
          return {
            ...parsed,
            uid: e.uid,
            content: String(e.content || ''),
            summary: extractSummary(e.content),
            keys: collectKeys(e, parsed),
          };
        })
        .filter(Boolean);
      state.initError = state.index.length ? null : '世界书条目均无合法 comment（格式 ID｜名称｜类别｜P<n>）';
      state.snapshot = []; state.lastInjected = []; state.missCount = {}; // 旧索引对象全部作废
      log('init', `索引完成：${state.index.length} 条条目（世界书「${wbName}）」`);
    } catch (e) {
      state.initError = '索引构建失败：' + (e && e.message);
      log('init', state.initError);
    }
  }

  function legalEntries(stage) {
    // 阶段门禁第一道：目录与检索候选只含 阶段 ≤ 当前阶段 的条目
    return state.index.filter((e) => e.stage <= stage);
  }

  // ================= 最近正文读取 =================
  function latestFloorId() {
    try {
      const arr = [].concat(api.getChatMessages ? api.getChatMessages(-1) : []);
      return arr.length && arr[0] && Number.isInteger(arr[0].message_id) ? arr[0].message_id : -1;
    } catch (_) { return -1; }
  }

  function recentFloors(count) {
    const last = latestFloorId();
    if (last < 0 || !api.getChatMessages) return [];
    const begin = Math.max(0, last - count + 1);
    try { return api.getChatMessages(`${begin}-${last}`) || []; } catch (_) { return []; }
  }

  function recentPlot(count, perFloorChars) {
    return recentFloors(count)
      .map((m) => String(m.message || '').trim())
      .filter(Boolean)
      .map((t) => (t.length > perFloorChars ? t.slice(0, perFloorChars) + '…' : t))
      .join('\n---\n');
  }

  // ================= 第 1 层：关键词扫描（同步，0 请求） =================
  function keywordScan(stage) {
    const text = recentFloors(CONFIG.KEYWORD_SCAN_FLOORS)
      .map((m) => String(m.message || ''))
      .join('\n')
      .toLowerCase();
    if (!text) return [];
    const hits = [];
    for (const e of legalEntries(stage)) {
      if (e.keys.some((k) => text.includes(k.toLowerCase()))) hits.push(e);
    }
    return hits;
  }

  // ================= 第 2 层：分类检索（异步，每类 1 次 generateRaw） =================
  function buildRetrievalPrompts(cat, entries) {
    const catalog = entries.map((e) => `${e.entryId}｜${e.name}｜${e.summary}`).join('\n');
    const system = [
      '你是世界书检索器。任务：对照最近剧情，从条目目录中选出与剧情、人物、地点、势力、事件、人物关系相关的条目。',
      '规则：只能选目录里存在的条目 ID，不得编造；按相关性选择，宁多勿漏；没有相关条目就给空列表。',
      '输出格式：只输出一个 JSON 对象 {"inject":[{"id":"条目ID","reason":"一句话理由"}]}，禁止输出其他内容。',
    ].join('\n');
    const user = `【最近剧情】\n${recentPlot(CONFIG.RETRIEVAL_CONTEXT_FLOORS, CONFIG.RETRIEVAL_FLOOR_CHARS)}\n\n【${cat.name}类条目目录（共 ${entries.length} 条）】\n${catalog}`;
    return [
      { role: 'system', content: system },
      { role: 'user', content: user },
    ];
  }

  function parseInjectJSON(raw) {
    const m = String(raw || '').match(/\{[\s\S]*\}/);
    if (!m) return null;
    try {
      const obj = JSON.parse(m[0]);
      if (!obj || !Array.isArray(obj.inject)) return null;
      return obj.inject.filter((x) => x && typeof x.id === 'string' && x.id);
    } catch (_) { return null; }
  }

  async function runRetrievalPass() {
    if (state.busy || !api.generateRaw || !state.index.length) return;
    state.busy = true;
    const stage = currentStage();
    const byCat = {};
    for (const e of legalEntries(stage)) (byCat[e.category] = byCat[e.category] || []).push(e);

    try {
      // 五类并行：Promise.all 同时发出，总耗时 ≈ 最慢的那一类
      const results = await Promise.all(CONFIG.CATEGORIES.map(async (cat) => {
        const entries = byCat[cat.id] || [];
        if (!entries.length) return [];
        const prompts = buildRetrievalPrompts(cat, entries);
        for (let attempt = 1; attempt <= 2; attempt++) { // JSON 非法重试 1 次
          try {
            const raw = String(await api.generateRaw({
              ordered_prompts: prompts, // 显式构造提示词序列，不带聊天历史
              should_silence: true,     // 静默生成，不写进聊天记录
              max_chat_history: 0,      // 不附加任何历史楼层
            }) || '');
            const picks = parseInjectJSON(raw);
            if (picks) {
              // 只保留真实存在且类别吻合的条目，防模型编 ID
              const valid = new Set(entries.map((e) => e.entryId));
              return picks.filter((p) => valid.has(p.id)).map((p) => ({ ...p, cat: cat.id }));
            }
          } catch (_) { /* 网络/API 异常 → 重试 */ }
        }
        return []; // 该类两次都失败 → 本轮该类空手，由关键词层兜底
      }));
      state.snapshot = results.flat();
      log('retrieval', `分类检索完成：候选 ${state.snapshot.length} 条（${results.map((r) => r.length).join('/')} 按类）`);
    } finally {
      state.busy = false;
      if (state.pending) { state.pending = false; kick('pending'); }
    }
  }

  function kick(reason) {
    if (state.busy) { state.pending = true; return; }
    log('trigger', '检索触发：' + reason);
    runRetrievalPass().catch(() => {});
  }

  // ================= 阶段注记截断（红线：后期情报不得进入早期提示词） =================
  function trimStageNotes(content, stage) {
    const lines = String(content || '').split('\n');
    const out = [];
    let inNotes = false, keptAny = false, headerIdx = -1;
    for (const line of lines) {
      const t = line.trim();
      if (/^##\s*阶段注记/.test(t)) { inNotes = true; keptAny = false; headerIdx = out.length; out.push(line); continue; }
      if (inNotes && /^##\s/.test(t)) { // 进入下一个章节
        if (!keptAny && headerIdx >= 0) out.splice(headerIdx); // 注记全被删 → 连标题移除
        inNotes = false;
      }
      if (inNotes) {
        const m = t.match(/^[-*]\s*P(\d+)\+/);
        if (m && Number(m[1]) > stage) continue; // 超前阶段行：丢弃
        if (m) keptAny = true;
      }
      out.push(line);
    }
    if (inNotes && !keptAny && headerIdx >= 0) out.splice(headerIdx);
    return out.join('\n');
  }

  // ================= 合并 + 预算 + 组装（生成前同步执行） =================
  function estimateTokens(text) { return Math.ceil(String(text).length / CONFIG.CHARS_PER_TOKEN); }

  function mergeAndBuild(stage) {
    const legalMap = new Map(legalEntries(stage).map((e) => [e.entryId, e]));
    const kwHits = keywordScan(stage).filter((e) => legalMap.has(e.entryId));
    const retrievalHits = [];
    for (const p of state.snapshot) {
      const e = legalMap.get(p.id);
      if (e && !retrievalHits.some((x) => x.entryId === e.entryId)) retrievalHits.push(e);
    }

    // 持续在场：对比上一楼注入集合。本轮两层都命中 → 计数清零；
    // 未命中 → 计数 +1，未达阈值前继续保留（防资料隔楼闪断）。
    const currentIds = new Set([...kwHits, ...retrievalHits].map((e) => e.entryId));
    const kept = [];
    for (const e of state.lastInjected) {
      if (currentIds.has(e.entryId)) { state.missCount[e.entryId] = 0; continue; }
      state.missCount[e.entryId] = (state.missCount[e.entryId] || 0) + 1;
      if (state.missCount[e.entryId] < CONFIG.PERSIST_MISS_FLOORS) kept.push(e);
    }

    // 合并去重，优先级：关键词 > 检索 > 持续保留（截断时按此顺序牺牲）
    const seen = new Set();
    const ordered = [];
    for (const tier of [kwHits, retrievalHits, kept]) {
      for (const e of tier) {
        if (!seen.has(e.entryId) && legalMap.has(e.entryId)) { seen.add(e.entryId); ordered.push(e); }
      }
    }

    // 预算：关键词层与检索层各自计账，超限即停该层并标记截断
    const kwIds = new Set(kwHits.map((e) => e.entryId));
    let kwTokens = 0, retTokens = 0, truncated = false;
    const blocks = ['【世界书资料（agent 注入）】'];
    const finalSet = [];
    for (const e of ordered) {
      const cost = estimateTokens(e.content);
      const tier = kwIds.has(e.entryId) ? 'kw' : (retrievalHits.includes(e) ? 'ret' : 'keep');
      if (tier === 'kw') {
        if (kwTokens + cost > CONFIG.KEYWORD_TOKEN_BUDGET) { truncated = true; continue; }
        kwTokens += cost;
      } else {
        if (retTokens + cost > CONFIG.RETRIEVAL_TOKEN_BUDGET) { truncated = true; continue; }
        retTokens += cost;
      }
      blocks.push(`【世界书·${e.entryId}｜${e.name}】\n${trimStageNotes(e.content, stage).trim()}`);
      finalSet.push({ ...e, _tier: tier }); // 副本带来源层标记，供面板显示
    }

    return {
      text: blocks.join('\n\n'),
      stats: {
        count: finalSet.length, kw: kwHits.length, ret: retrievalHits.length,
        keep: kept.length, truncated, finalSet,
      },
    };
  }

  // ================= 生成前同步钩子（注入唯一入口） =================
  function onGenerationHook() {
    try {
      if (!api.injectPrompts || !api.uninjectPrompts || !state.index.length) return;
      const stage = currentStage();
      const { text, stats } = mergeAndBuild(stage);

      try { api.uninjectPrompts([INJECT_ID]); } catch (_) {} // 同 id 重复注入不会自动覆盖，必须先撤
      if (stats.count > 0) {
        api.injectPrompts([{
          id: INJECT_ID,
          position: 'in_chat',   // 插进聊天楼层之间
          depth: CONFIG.INJECT_DEPTH,
          role: CONFIG.INJECT_ROLE,
          content: text,
          once: true,            // 本次生成用完即清，下楼重新算，不留陈旧资料
        }], { once: true });
      }
      state.lastInjected = stats.finalSet;
      log('inject', `注入 ${stats.count} 条（关键词${stats.kw}/检索${stats.ret}/保留${stats.keep}，约 ${estimateTokens(text)} tokens）${stats.truncated ? '｜已按优先级截断' : ''}`);
    } catch (e) {
      log('inject', '注入钩子异常：' + (e && e.message)); // 钩子抛错可能影响生成，必须吞掉
    }
  }

  // ================= 悬浮窗（宿主文档挂载，范式 C11/C1） =================
  const UI = {
    ROOT_ID: 'doupo-wb-agent-ui',
    STYLE_ID: 'doupo-wb-agent-style',
    BALL_ID: 'dpwa-ball',
    PANEL_ID: 'dpwa-panel',
    LS_KEY: 'doupo-wb-agent:orb-v1',
    root: null, style: null, ball: null, panel: null,
    open: false, timer: null, gesture: null,
  };
  const DRAG_THRESHOLD = 5; // 位移超过 5px 判定为拖动，否则视为点击（C11 §4.2）
  const BALL_R = 24;        // 球半径（热区 48px，满足 44px 下限）

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
      { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    ));
  }

  function agentStatus() {
    // 绿=索引就绪；黄=检索进行中；红=初始化异常
    if (state.initError) return { cls: 'bad', text: state.initError };
    if (state.busy) return { cls: 'warn', text: '分类检索进行中…' };
    if (!state.index.length) return { cls: 'bad', text: '索引为空' };
    return { cls: 'ok', text: `世界书「${state.worldbookName || '?'}」· 索引 ${state.index.length} 条` };
  }

  const UI_CSS = `
    #${UI.ROOT_ID} * { box-sizing: border-box; margin: 0; padding: 0; font-family: inherit; }
    #${UI.BALL_ID} {
      position: fixed; width: 48px; height: 48px; border-radius: 50%;
      background: linear-gradient(145deg, #2b3a67, #1a2440); color: #e8d9b0;
      border: 1px solid #5a6b9e; box-shadow: 0 2px 10px rgba(0,0,0,.45);
      font-size: 20px; line-height: 46px; text-align: center; cursor: pointer;
      z-index: 99998; touch-action: none; user-select: none; padding: 0;
    }
    #${UI.BALL_ID} .dot {
      position: absolute; top: 2px; right: 2px; width: 10px; height: 10px;
      border-radius: 50%; border: 1px solid rgba(0,0,0,.4);
    }
    .dot.ok { background: #4caf50; } .dot.warn { background: #ffb300; } .dot.bad { background: #e53935; }
    #${UI.PANEL_ID} {
      position: fixed; width: min(380px, 92vw); max-height: min(72vh, 560px);
      overflow-y: auto; z-index: 99999;
      background: #16181dee; color: #d6d6de; border: 1px solid #3a3f55;
      border-radius: 10px; box-shadow: 0 6px 24px rgba(0,0,0,.55);
      font-size: 12.5px; line-height: 1.55;
    }
    .dpwa-head {
      position: sticky; top: 0; display: flex; align-items: center; gap: 8px;
      padding: 9px 12px; background: #1d2030; border-bottom: 1px solid #3a3f55;
      font-weight: 600; font-size: 13px; color: #e8d9b0;
    }
    .dpwa-head .grow { flex: 1; }
