    @media (prefers-reduced-motion: reduce) { #${UI.ROOT_ID} * { transition: none !important; animation: none !important; } }
  `;

  function savePlacement(fx, fy) {
    try {
      hostWindow().localStorage.setItem(UI.LS_KEY, JSON.stringify({ version: 1, fx, fy }));
    } catch (_) {}
  }

  function loadPlacement() {
    try {
      const raw = hostWindow().localStorage.getItem(UI.LS_KEY);
      if (!raw) return null;
      const d = JSON.parse(raw);
      if (d.version !== 1) return null;
      const fx = Math.min(1, Math.max(0, Number(d.fx)));
      const fy = Math.min(1, Math.max(0, Number(d.fy)));
      if (!Number.isFinite(fx) || !Number.isFinite(fy)) return null;
      return { fx, fy };
    } catch (_) { return null; }
  }

  // 归一化坐标 → 像素并夹取进可视视口（C11 §5.1：不信任旧像素）
  function applyPlacement(fx, fy) {
    const hw = hostWindow();
    const vw = Math.max(320, hw.innerWidth || 0);
    const vh = Math.max(240, hw.innerHeight || 0);
    const x = Math.min(vw - BALL_R - 2, Math.max(BALL_R + 2, fx * vw));
    const y = Math.min(vh - BALL_R - 2, Math.max(BALL_R + 2, fy * vh));
    UI.ball.style.left = (x - BALL_R) + 'px';
    UI.ball.style.top = (y - BALL_R) + 'px';
  }

  function placePanel() {
    const hw = hostWindow();
    const vw = Math.max(320, hw.innerWidth || 0);
    const vh = Math.max(240, hw.innerHeight || 0);
    const br = UI.ball.getBoundingClientRect();
    const pw = Math.min(380, vw * 0.92);
    const ph = Math.min(560, vh * 0.72);
    // 球在右半屏 → 面板往左开；否则往右开；上下夹取
    const left = br.left > vw / 2
      ? Math.max(6, Math.min(vw - pw - 6, br.left - pw - 10))
      : Math.max(6, Math.min(vw - pw - 6, br.right + 10));
    const top = Math.max(6, Math.min(vh - ph - 6, br.top - 8));
    UI.panel.style.left = left + 'px';
    UI.panel.style.top = top + 'px';
  }

  function renderPanel() {
    if (!UI.open || !UI.panel) return;
    const st = agentStatus();
    const stage = currentStage();
    const tierName = { kw: '关键词', ret: '检索', keep: '保留' };

    const inj = state.lastInjected.length
      ? state.lastInjected.map((e) =>
          `<li><span class="tag ${esc(e._tier)}">${tierName[e._tier] || '?'}</span>${esc(e.entryId)}｜${esc(e.name)}</li>`).join('')
      : '<div class="dpwa-empty">本楼尚未注入（生成时才计算并注入）</div>';

    const cand = state.snapshot.length
      ? state.snapshot.map((p) =>
          `<li>${esc(p.id)}<span class="why">｜${esc(p.reason || '')}</span></li>`).join('')
      : '<div class="dpwa-empty">暂无检索候选</div>';

    const logs = readLog().slice(-12).reverse();
    const logHtml = logs.length
      ? logs.map((r) => `<li><b>[${esc(r.kind)}]</b> ${esc(r.t)} ${esc(r.detail)}</li>`).join('')
      : '<div class="dpwa-empty">暂无日志</div>';

    UI.panel.innerHTML = `
      <div class="dpwa-head">
        <span class="dot ${esc(st.cls)}"></span> 斗破世界书 Agent
        <span class="grow"></span>
        <button type="button" data-act="close" aria-label="关闭面板">×</button>
      </div>
      <div class="dpwa-status"><span class="dot ${esc(st.cls)}"></span>${esc(st.text)} · 阶段 P${stage}</div>
      <div class="dpwa-sec"><h4>最近注入（按来源层）</h4><ul>${inj}</ul></div>
      <div class="dpwa-sec"><h4>检索候选（最新一轮）</h4><ul>${cand}</ul></div>
      <div class="dpwa-sec dpwa-log"><h4>运行日志（wb_log 最近 12 条）</h4><ul>${logHtml}</ul></div>
      <div class="dpwa-actions">
        <button type="button" data-act="rerun">立即检索</button>
        <button type="button" data-act="reindex">重建索引</button>
        <button type="button" data-act="clearlog">清空日志</button>
      </div>
      <div class="dpwa-stage">
        阶段测试（写入聊天变量「${esc(CONFIG.STAGE_VAR)}」）：
        <input id="dpwa-stage-input" type="number" min="1" max="${CONFIG.STAGE_MAX}" value="${stage}">
        <button type="button" data-act="setstage">写入</button>
      </div>`;

    UI.panel.querySelectorAll('[data-act]').forEach((btn) => {
      btn.addEventListener('click', (ev) => { ev.stopPropagation(); onAction(btn.dataset.act); });
    });
  }

  function onAction(act) {
    const hw = hostWindow();
    const toast = (msg) => { try { if (typeof hw.toastr !== 'undefined' && hw.toastr) hw.toastr.info(msg, '[斗破] Agent'); } catch (_) {} };
    if (act === 'close') { closePanel(); return; }
    if (act === 'rerun') { kick('manual'); toast('已触发一轮分类检索'); renderPanel(); return; }
    if (act === 'reindex') { rebuildIndex().then(renderPanel); toast('正在重建索引'); return; }
    if (act === 'clearlog') {
      try {
        const vars = api.getVariables ? api.getVariables({ type: 'chat' }) : null;
        if (vars) { vars.wb_log = []; api.replaceVariables(vars, { type: 'chat' }); }
      } catch (_) {}
      toast('wb_log 已清空'); renderPanel(); return;
    }
    if (act === 'setstage') {
      try {
        const input = UI.panel.querySelector('#dpwa-stage-input');
        const n = Number(input && input.value);
        if (!Number.isInteger(n) || n < 1 || n > CONFIG.STAGE_MAX) { toast('阶段必须是 1-' + CONFIG.STAGE_MAX); return; }
        const vars = api.getVariables ? api.getVariables({ type: 'chat' }) : {};
        vars[CONFIG.STAGE_VAR] = n;
        api.replaceVariables(vars, { type: 'chat' });
        log('stage', `手动写入 ${CONFIG.STAGE_VAR}=${n}（面板测试功能）`);
        toast(`已写入 ${CONFIG.STAGE_VAR}=${n}`);
        renderPanel();
      } catch (_) {}
    }
  }

  function openPanel() {
    UI.open = true;
    UI.panel.hidden = false;
    UI.ball.setAttribute('aria-expanded', 'true');
    placePanel();
    renderPanel();
    if (UI.timer) { try { hostWindow().clearInterval(UI.timer); } catch (_) {} }
    UI.timer = hostWindow().setInterval(renderPanel, 2000); // 展开期间 2 秒自刷
  }

  function closePanel() {
    UI.open = false;
    UI.panel.hidden = true;
    UI.ball.setAttribute('aria-expanded', 'false');
    if (UI.timer) { try { hostWindow().clearInterval(UI.timer); } catch (_) {} UI.timer = null; }
  }

  // ---- 手势仲裁（C11 §4.2：pointer 序列区分拖动与点击） ----
  function onBallPointerDown(ev) {
    if (!ev.isPrimary || (ev.pointerType === 'mouse' && ev.button !== 0)) return;
    if (UI.gesture) return;
    try { ev.currentTarget.setPointerCapture(ev.pointerId); } catch (_) {}
    UI.gesture = {
      pointerId: ev.pointerId, startX: ev.clientX, startY: ev.clientY,
      startLeft: parseFloat(UI.ball.style.left) || 0, startTop: parseFloat(UI.ball.style.top) || 0,
      dragging: false,
    };
  }
  function onBallPointerMove(ev) {
    if (!UI.gesture || ev.pointerId !== UI.gesture.pointerId) return;
    const dist = Math.hypot(ev.clientX - UI.gesture.startX, ev.clientY - UI.gesture.startY);
    if (dist > DRAG_THRESHOLD) UI.gesture.dragging = true;
    if (UI.gesture.dragging) {
      UI.ball.style.left = (UI.gesture.startLeft + ev.clientX - UI.gesture.startX) + 'px';
      UI.ball.style.top = (UI.gesture.startTop + ev.clientY - UI.gesture.startY) + 'px';
    }
  }
  function onBallPointerUp(ev) {
    if (!UI.gesture || ev.pointerId !== UI.gesture.pointerId) return;
    const wasDrag = UI.gesture.dragging;
    try { ev.currentTarget.releasePointerCapture(ev.pointerId); } catch (_) {}
    UI.gesture = null;
    if (wasDrag) {
      // 吸附到最近竖边 + 归一化持久化（C11 §5.2/5.3）
      const hw = hostWindow();
      const vw = Math.max(320, hw.innerWidth || 0);
      const vh = Math.max(240, hw.innerHeight || 0);
      const r = UI.ball.getBoundingClientRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      const snappedX = cx < vw / 2 ? BALL_R + 2 : vw - BALL_R - 2;
      const fx = snappedX / vw;
      const fy = Math.min(0.95, Math.max(0.05, cy / vh));
      applyPlacement(fx, fy);
      savePlacement(fx, fy);
      if (UI.open) placePanel();
    } else {
      UI.open ? closePanel() : openPanel();
    }
  }
  function onBallPointerCancel(ev) {
    if (!UI.gesture || ev.pointerId !== UI.gesture.pointerId) return;
    UI.gesture = null; // 系统手势打断：清临时态，不当成点击
  }

  function buildUI() {
    try {
      const doc = hostDocument();
      if (!doc || !doc.body) return;
      // 单例：先移除失去属主的旧节点（C11 §8.1）
      const old = doc.getElementById(UI.ROOT_ID);
      if (old) old.remove();
      const oldStyle = doc.getElementById(UI.STYLE_ID);
      if (oldStyle) oldStyle.remove();

      UI.style = doc.createElement('style');
      UI.style.id = UI.STYLE_ID;
      UI.style.textContent = UI_CSS;
      doc.head.appendChild(UI.style);

      UI.root = doc.createElement('div');
      UI.root.id = UI.ROOT_ID;
      UI.root.innerHTML = `
        <button id="${UI.BALL_ID}" type="button" aria-label="打开斗破世界书Agent面板"
                aria-controls="${UI.PANEL_ID}" aria-expanded="false"><span class="dot ok"></span>书</button>
        <div id="${UI.PANEL_ID}" role="dialog" aria-label="斗破世界书Agent面板" hidden></div>`;
      doc.body.appendChild(UI.root);

      UI.ball = doc.getElementById(UI.BALL_ID);
      UI.panel = doc.getElementById(UI.PANEL_ID);

      const placement = loadPlacement() || { fx: 0.94, fy: 0.38 }; // 默认右侧偏上
      applyPlacement(placement.fx, placement.fy);

      UI.ball.addEventListener('pointerdown', onBallPointerDown);
      UI.ball.addEventListener('pointermove', onBallPointerMove);
      UI.ball.addEventListener('pointerup', onBallPointerUp);
      UI.ball.addEventListener('pointercancel', onBallPointerCancel);

      // 面板展开时：点击空白处收起
      const onDocPointer = (ev) => {
        if (!UI.open) return;
        const t = ev.target;
        if (UI.panel.contains(t) || UI.ball.contains(t)) return;
        closePanel();
      };
      doc.addEventListener('pointerdown', onDocPointer, true);
      disposers.push(() => { try { doc.removeEventListener('pointerdown', onDocPointer, true); } catch (_) {} });

      // Escape 收起并归还焦点（C11 §7.2）
      const onKey = (ev) => {
        if (ev.key === 'Escape' && UI.open) { closePanel(); try { UI.ball.focus(); } catch (_) {} }
      };
      doc.addEventListener('keydown', onKey);
      disposers.push(() => { try { doc.removeEventListener('keydown', onKey); } catch (_) {} });

      log('init', '悬浮窗已挂载到宿主页面');
    } catch (e) {
      log('init', '悬浮窗挂载失败：' + (e && e.message));
    }
  }

  // ================= 事件接线与生命周期 =================
  function register(name, listener, first) {
    if (!name) return;
    try {
      const reg = (first && api.eventMakeFirst) ? api.eventMakeFirst : api.eventOn;
      if (!reg) return;
      const d = reg(name, listener);
      if (d && typeof d.stop === 'function') disposers.push(() => d.stop());
      else disposers.push(() => { try { d && d(); } catch (_) {} }); // 兼容旧版返回 void
    } catch (_) {}
  }

  function destroy() {
    try { if (UI.timer) hostWindow().clearInterval(UI.timer); } catch (_) {}
    try { UI.root && UI.root.remove(); } catch (_) {}
    try { UI.style && UI.style.remove(); } catch (_) {}
    while (disposers.length) { try { disposers.pop()(); } catch (_) {} }
    try { api.uninjectPrompts && api.uninjectPrompts([INJECT_ID]); } catch (_) {}
    delete window.__DOUPO_WB_AGENT__;
  }

  function install() {
    // 生成前三时机全部订阅 + 插队（生产范式：保证不同 ST/TH 版本兼容）
    [EV.GENERATION_AFTER_COMMANDS, EV.GENERATE_BEFORE_COMBINE_PROMPTS, EV.CHAT_COMPLETION_PROMPT_READY]
      .filter(Boolean)
      .forEach((name) => register(name, onGenerationHook, true));

    // 每条消息后异步跑检索，为下一楼准备快照
    register(EV.MESSAGE_SENT, () => kick('message_sent'));
    register(EV.MESSAGE_RECEIVED, () => kick('message_received'));
    register(EV.CHAT_CHANGED, () => {
      state.snapshot = []; state.lastInjected = []; state.missCount = {};
      rebuildIndex().then(() => kick('chat_changed'));
    });

    // 页面卸载前清理（C11 §8.2）
    try { hostWindow().addEventListener('pagehide', () => destroy(), { once: true }); } catch (_) {}

    window.__DOUPO_WB_AGENT__ = { destroy };
    buildUI();          // 悬浮球：脚本启用即出现在 ST 页面上
    log('init', 'agent 雏形 v0.2 已启动（含悬浮窗）');
    rebuildIndex().then(() => kick('startup'));
  }

  install();
})();

